package org.apache.commons.collections4.sequence;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Random;

import org.apache.commons.lang3.StringUtils;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

class SequencesComparatorTest {

    private static final String[] SHADOK_ALPHABET = {
        "GA",
        "BU",
        "ZO",
        "MEU"
    };

    private static final class ExecutionVisitor<T> implements CommandVisitor<T> {

        private List<T> transformedSequence;
        private int currentIndex;

        public String getString() {
            final StringBuilder buffer = new StringBuilder();
            for (final T element : transformedSequence) {
                buffer.append(element);
            }
            return buffer.toString();
        }

        public void setList(final List<T> sequence) {
            transformedSequence = new ArrayList<>(sequence);
            currentIndex = 0;
        }

        @Override
        public void visitDeleteCommand(final T object) {
            transformedSequence.remove(currentIndex);
        }

        @Override
        public void visitInsertCommand(final T object) {
            transformedSequence.add(currentIndex++, object);
        }

        @Override
        public void visitKeepCommand(final T object) {
            ++currentIndex;
        }

    }

    private List<String> before;
    private List<String> after;
    private int[] modificationCounts;

    private List<Character> sequence(final String string) {
        final List<Character> list = new ArrayList<>();
        for (int i = 0; i < string.length(); ++i) {
            list.add(Character.valueOf(string.charAt(i)));
        }
        return list;
    }

    @BeforeEach
    public void setUp() {
        before = Arrays.asList(
            "bottle",
            "nematode knowledge",
            StringUtils.EMPTY,
            "aa",
            "prefixed string",
            "ABCABBA",
            "glop glop",
            "coq",
            "spider-man");

        after = Arrays.asList(
            "noodle",
            "empty bottle",
            StringUtils.EMPTY,
            "C",
            "prefix",
            "CBABAC",
            "pas glop pas glop",
            "ane",
            "klingon");

        modificationCounts = new int[] {
            6,
            16,
            0,
            3,
            9,
            5,
            8,
            6,
            13
        };
    }

    @AfterEach
    public void tearDown() {
        before = null;
        after = null;
        modificationCounts = null;
    }

    @Test
    void testExecution() {
        final ExecutionVisitor<Character> ev = new ExecutionVisitor<>();
        for (int i = 0; i < before.size(); ++i) {
            ev.setList(sequence(before.get(i)));
            new SequencesComparator<>(sequence(before.get(i)), sequence(after.get(i))).getScript().visit(ev);
            assertEquals(after.get(i), ev.getString());
        }
    }

    @Test
    void testLength() {
        for (int i = 0; i < before.size(); ++i) {
            final SequencesComparator<Character> comparator =
                    new SequencesComparator<>(sequence(before.get(i)), sequence(after.get(i)));
            assertEquals(modificationCounts[i], comparator.getScript().getModifications());
        }
    }

    @Test
    void testMinimal() {
        final List<String> sentenceBefore = new ArrayList<>();
        final List<String> sentenceAfter = new ArrayList<>();
        sentenceBefore.add(SHADOK_ALPHABET[0]);
        sentenceBefore.add(SHADOK_ALPHABET[2]);
        sentenceBefore.add(SHADOK_ALPHABET[3]);
        sentenceBefore.add(SHADOK_ALPHABET[1]);
        sentenceBefore.add(SHADOK_ALPHABET[0]);
        sentenceBefore.add(SHADOK_ALPHABET[0]);
        sentenceBefore.add(SHADOK_ALPHABET[2]);
        sentenceBefore.add(SHADOK_ALPHABET[1]);
        sentenceBefore.add(SHADOK_ALPHABET[3]);
        sentenceBefore.add(SHADOK_ALPHABET[0]);
        sentenceBefore.add(SHADOK_ALPHABET[2]);
        sentenceBefore.add(SHADOK_ALPHABET[1]);
        sentenceBefore.add(SHADOK_ALPHABET[3]);
        sentenceBefore.add(SHADOK_ALPHABET[2]);
        sentenceBefore.add(SHADOK_ALPHABET[2]);
        sentenceBefore.add(SHADOK_ALPHABET[0]);
        sentenceBefore.add(SHADOK_ALPHABET[1]);
        sentenceBefore.add(SHADOK_ALPHABET[3]);
        sentenceBefore.add(SHADOK_ALPHABET[0]);
        sentenceBefore.add(SHADOK_ALPHABET[3]);

        final Random random = new Random(4564634237452342L);

        for (int nbCom = 0; nbCom <= 40; nbCom += 5) {
            sentenceAfter.clear();
            sentenceAfter.addAll(sentenceBefore);
            for (int i = 0; i < nbCom; i++) {
                if (random.nextInt(2) == 0) {
                    sentenceAfter.add(random.nextInt(sentenceAfter.size() + 1),
                            SHADOK_ALPHABET[random.nextInt(4)]);
                } else {
                    sentenceAfter.remove(random.nextInt(sentenceAfter.size()));
                }
            }

            final SequencesComparator<String> comparator = new SequencesComparator<>(sentenceBefore, sentenceAfter);
            assertTrue(comparator.getScript().getModifications() <= nbCom);
        }
    }

    @Test
    void testShadok() {
        final int lgMax = 5;
        List<List<String>> shadokSentences = new ArrayList<>();
        for (int lg = 0; lg < lgMax; ++lg) {
            final List<List<String>> newTab = new ArrayList<>();
            newTab.add(new ArrayList<>());
            for (final String element : SHADOK_ALPHABET) {
                for (final List<String> sentence : shadokSentences) {
                    final List<String> newSentence = new ArrayList<>(sentence);
                    newSentence.add(element);
                    newTab.add(newSentence);
                }
            }
            shadokSentences = newTab;
        }

        final ExecutionVisitor<String> ev = new ExecutionVisitor<>();

        for (final List<String> element : shadokSentences) {
            for (final List<String> shadokSentence : shadokSentences) {
                ev.setList(element);
                new SequencesComparator<>(element, shadokSentence).getScript().visit(ev);

                final StringBuilder concat = new StringBuilder();
                for (final String s : shadokSentence) {
                    concat.append(s);
                }
                assertEquals(concat.toString(), ev.getString());
            }
        }
    }

}
